/* RCV Analytics - Chart.js helpers  (Chart.js 3.7.x) */

/* Filtros activos de la página, como lista de [etiqueta, valor].
   Lo sobrescribe rcv_print_active_filters_js(); este valor por defecto evita un
   ReferenceError si la página no lo emite. */
var rcvActiveFilters = [];

var RCV_COLORS = [
    '#1d4ed8', // azul fuerte
    '#475569', // gris pizarra
    '#2563eb', // azul medio
    '#64748b', // gris medio
    '#3b82f6', // azul claro
    '#94a3b8', // gris claro
    '#1e3a8a', // azul muy oscuro
    '#334155', // gris oscuro
    '#60a5fa', // azul suave
    '#cbd5e1', // gris muy claro
    '#0369a1', // azul acero
    '#0c4a6e', // azul marino
];

function rcvGetColors(count) {
    var colors = [];
    for (var i = 0; i < count; i++) {
        colors.push(RCV_COLORS[i % RCV_COLORS.length]);
    }
    return colors;
}

function rcvNoData(canvasId) {
    var box = document.getElementById(canvasId);
    if (!box) return;
    box.style.display = 'none';
    var msg = document.createElement('div');
    msg.style.cssText = 'color:#94a3b8;font-size:.85em;text-align:center;padding:32px 0;';
    msg.textContent = 'Sin datos disponibles';
    box.parentNode.appendChild(msg);
}

/**
 * Dibuja valores numéricos sobre cada barra.
 * Usado como inline plugin afterDraw — se ejecuta en cada render, incluido
 * resize, por lo que las etiquetas siempre son visibles.
 */
function rcvDrawBarLabels(chart) {
    var ctx     = chart.ctx;
    var areaTop = chart.chartArea ? chart.chartArea.top : 0;

    chart.data.datasets.forEach(function(dataset, i) {
        var meta = chart.getDatasetMeta(i);
        if (meta.hidden) return;
        meta.data.forEach(function(bar, index) {
            var value = dataset.data[index];
            if (!value) return;

            /* En Chart.js 3.x bar.x y bar.y son propiedades directas */
            var x = bar.x, y = bar.y;
            if (x === undefined || y === undefined) return;

            /* Si hay ≥16 px de espacio arriba → dibujar encima;
               si no (barra muy alta o chart muy comprimido) → dibujar dentro */
            var textY, baseline;
            if (y - areaTop >= 16) {
                textY    = y - 4;
                baseline = 'bottom';
            } else {
                textY    = y + 14;
                baseline = 'top';
            }

            ctx.save();
            ctx.fillStyle    = '#000';
            ctx.font         = 'bold 12px sans-serif';
            ctx.textAlign    = 'center';
            ctx.textBaseline = baseline;
            ctx.fillText(value, x, textY);
            ctx.restore();
        });
    });
}

/* Plugin inline reutilizable — sin id para evitar conflictos al usarlo en múltiples charts */
function rcvMakeBarLabelPlugin() {
    return {
        afterDraw: function(chart) { rcvDrawBarLabels(chart); }
    };
}

function rcvRenderLineChart(canvasId, chartData, datasetLabel) {
    var ctx = document.getElementById(canvasId);
    if (!ctx || !chartData || !chartData.labels || !chartData.labels.length) { rcvNoData(canvasId); return; }
    try {
    new Chart(ctx, {
        type: 'line',
        data: {
            labels: chartData.labels,
            datasets: [{
                label: datasetLabel || '',
                data: chartData.data,
                borderColor: RCV_COLORS[0],
                backgroundColor: RCV_COLORS[0] + '22',
                fill: true,
                tension: 0.3,
                pointRadius: 4,
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: { legend: { display: false } },
            scales: { y: { beginAtZero: true, ticks: { precision: 0, color: '#000' } }, x: { ticks: { color: '#000' } } }
        }
    });
    } catch(e) { console.error('rcvRenderLineChart error:', e); rcvNoData(canvasId); }
}

function rcvRenderBarChart(canvasId, chartData, datasetLabel) {
    var ctx = document.getElementById(canvasId);
    if (!ctx || !chartData || !chartData.labels || !chartData.labels.length) { rcvNoData(canvasId); return; }
    var displayLabels = chartData.labels.map(function(l) {
        return (l && l.length > 25) ? l.substring(0, 22) + '...' : l;
    });
    var maxVal = Math.max.apply(null, chartData.data);
    try {
    new Chart(ctx, {
        type: 'bar',
        data: {
            labels: displayLabels,
            datasets: [{
                label: datasetLabel || '',
                data: chartData.data,
                backgroundColor: rcvGetColors(chartData.data.length),
                borderRadius: 4,
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
                legend: { display: false },
                tooltip: {
                    mode: 'index',
                    intersect: false,
                    callbacks: {
                        title: function(items) {
                            return chartData.labels[items[0].dataIndex] || '';
                        }
                    }
                }
            },
            scales: {
                y: {
                    beginAtZero: true,
                    ticks: { precision: 0, color: '#000' },
                    suggestedMax: maxVal > 0 ? Math.ceil(maxVal * 1.2) : 10
                },
                x: { ticks: { maxRotation: 45, minRotation: 0, autoSkip: true, maxTicksLimit: 100, font: { size: 11 }, color: '#000' } }
            }
        },
        plugins: [rcvMakeBarLabelPlugin()]
    });
    } catch(e) { console.error('rcvRenderBarChart error:', e); rcvNoData(canvasId); }
}

/**
 * Dibuja porcentaje y valor en cada segmento de un doughnut.
 * Segmentos grandes (≥5%): etiqueta dentro del arco.
 * Segmentos pequeños (<5%): línea guía hacia afuera con etiqueta lateral.
 * Incluye resolución de colisiones verticales en etiquetas exteriores.
 */
function rcvDrawDoughnutLabels(chart) {
    var ctx     = chart.ctx;
    var dataset = chart.data.datasets[0];
    if (!dataset) return;
    var total = dataset.data.reduce(function(a, b) { return a + (b || 0); }, 0);
    if (!total) return;

    var meta = chart.getDatasetMeta(0);
    if (meta.hidden) return;

    var outsideLabels = [];

    meta.data.forEach(function(arc, index) {
        var value = dataset.data[index];
        if (!value) return;
        var pct      = value / total * 100;
        var midAngle = (arc.startAngle + arc.endAngle) / 2;
        var cosA     = Math.cos(midAngle);
        var sinA     = Math.sin(midAngle);
        var cx = arc.x, cy = arc.y;

        if (pct >= 5) {
            // ── etiqueta dentro del arco ──────────────────────────────────────
            var r = (arc.outerRadius + arc.innerRadius) / 2;
            var x = cx + cosA * r;
            var y = cy + sinA * r;
            ctx.save();
            ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
            ctx.fillStyle = '#fff'; ctx.font = 'bold 11px sans-serif';
            ctx.fillText(Math.round(pct) + '%', x, y - 6);
            ctx.font = '10px sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.85)';
            ctx.fillText(value, x, y + 7);
            ctx.restore();

        } else if (pct >= 1) {
            // ── acumular para resolver colisiones después ─────────────────────
            var r1      = arc.outerRadius + 5;
            var r2      = arc.outerRadius + 18;
            var onRight = cosA >= 0;
            outsideLabels.push({
                x1: cx + cosA * r1, y1: cy + sinA * r1,
                x2: cx + cosA * r2, y2: cy + sinA * r2,
                onRight: onRight,
                text: Math.round(pct) + '% (' + value + ')'
            });
        }
    });

    // ── resolver colisiones verticales por lado ───────────────────────────────
    var lineH = 14;
    ['right', 'left'].forEach(function(side) {
        var group = outsideLabels
            .filter(function(l) { return l.onRight === (side === 'right'); })
            .sort(function(a, b) { return a.y2 - b.y2; });

        // Empujar hacia abajo los que se solapan
        for (var i = 1; i < group.length; i++) {
            if (group[i].y2 - group[i-1].y2 < lineH) {
                group[i].y2 = group[i-1].y2 + lineH;
            }
        }
        // Empujar hacia arriba si se pasaron del canvas
        var canvasH = chart.canvas.height / (window.devicePixelRatio || 1);
        for (var j = group.length - 1; j >= 1; j--) {
            if (group[j].y2 > canvasH - 5) group[j].y2 = canvasH - 5;
            if (group[j].y2 - group[j-1].y2 < lineH) {
                group[j-1].y2 = group[j].y2 - lineH;
            }
        }
    });

    // ── dibujar etiquetas exteriores ──────────────────────────────────────────
    outsideLabels.forEach(function(l) {
        var elbowLen = 14;
        var xElbow   = l.x2 + (l.onRight ? elbowLen : -elbowLen);
        var textX    = xElbow + (l.onRight ? 3 : -3);

        ctx.save();
        ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(l.x1, l.y1);
        ctx.lineTo(l.x2, l.y2);
        ctx.lineTo(xElbow, l.y2);
        ctx.stroke();

        ctx.fillStyle = '#1e293b'; ctx.font = '10px sans-serif';
        ctx.textAlign = l.onRight ? 'left' : 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(l.text, textX, l.y2);
        ctx.restore();
    });
}

function rcvMakeDoughnutLabelPlugin() {
    return { afterDraw: function(chart) { rcvDrawDoughnutLabels(chart); } };
}

function rcvRenderDoughnutChart(canvasId, chartData) {
    var ctx = document.getElementById(canvasId);
    if (!ctx || !chartData || !chartData.labels || !chartData.labels.length) { rcvNoData(canvasId); return; }

    var box = ctx.closest('.rcv-chart-box');
    if (box) box.style.height = '450px';

    try {
    new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: chartData.labels,
            datasets: [{
                data: chartData.data,
                backgroundColor: rcvGetColors(chartData.data.length),
                borderWidth: 2,
            }]
        },
        options: {
            animation: false,
            responsive: true,
            maintainAspectRatio: false,
            layout: { padding: { top: 30, bottom: 30, left: 55, right: 55 } },
            plugins: {
                legend: {
                    position: 'bottom',
                    labels: { font: { size: 13, weight: '600' }, color: '#1e293b', boxWidth: 13, padding: 12 }
                },
                tooltip: {
                    callbacks: {
                        label: function(item) {
                            var total = item.dataset.data.reduce(function(a,b){return a+(b||0);},0);
                            var pct = total ? Math.round(item.parsed / total * 100) : 0;
                            return ' ' + item.label + ': ' + item.parsed + ' (' + pct + '%)';
                        }
                    }
                }
            }
        },
        plugins: [rcvMakeDoughnutLabelPlugin()]
    });
    } catch(e) { console.error('rcvRenderDoughnutChart error:', e); rcvNoData(canvasId); }
}

function rcvRenderStackedBarChart(canvasId, chartData) {
    /* chartData = { labels:[], datasets:[{label, data:[]},...] } */
    var ctx = document.getElementById(canvasId);
    if (!ctx || !chartData || !chartData.labels || !chartData.labels.length) { rcvNoData(canvasId); return; }
    var ds = chartData.datasets.map(function(d, i) {
        return Object.assign({ backgroundColor: RCV_COLORS[i % RCV_COLORS.length] }, d);
    });
    var maxVal = 0;
    chartData.labels.forEach(function(_, i) {
        var col = ds.reduce(function(s, d) { return s + (d.data[i] || 0); }, 0);
        if (col > maxVal) maxVal = col;
    });
    try {
    new Chart(ctx, {
        type: 'bar',
        data: { labels: chartData.labels, datasets: ds },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: { mode: 'index', intersect: false },
            plugins: {
                legend: { position: 'bottom', labels: { font: { size: 11 }, boxWidth: 12, padding: 8 } },
                tooltip: { mode: 'index', intersect: false }
            },
            scales: {
                x: { stacked: true },
                y: {
                    stacked: true,
                    beginAtZero: true,
                    ticks: { precision: 0 },
                    suggestedMax: maxVal > 0 ? Math.ceil(maxVal * 1.2) : 10
                }
            }
        },
        plugins: [rcvMakeBarLabelPlugin()]
    });
    } catch(e) { console.error('rcvRenderStackedBarChart error:', e); rcvNoData(canvasId); }
}


/**
 * Export all charts and tables to PDF.
 * Requires jsPDF (window.jspdf.jsPDF) and html2canvas on the page.
 *
 * @param {string} pdfTitle    Título impreso en la cabecera
 * @param {string} filePrefix  Prefijo del nombre de archivo
 * @param {Array}  filters     Opcional. Lista de [etiqueta, valor] con los filtros
 *                             activos; se imprime bajo la cabecera para dejar
 *                             constancia del alcance de los datos exportados.
 */
function rcvExportChartsPDF(pdfTitle, filePrefix, filters) {
    if (typeof window.jspdf === 'undefined' || typeof html2canvas === 'undefined') {
        alert('Las librerías de exportación PDF aún no han cargado. Intente de nuevo en unos segundos.');
        return;
    }

    var btn = document.querySelector('.rcv-btn-export-pdf');
    if (btn) btn.disabled = true;

    var overlay = document.createElement('div');
    overlay.className = 'rcv-export-overlay';
    overlay.innerHTML = '<div class="rcv-export-overlay-inner">' +
        '<div class="rcv-spinner"></div>' +
        '<p>Generando PDF\u2026</p></div>';
    document.body.appendChild(overlay);

    function cleanup() {
        if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
        if (btn) btn.disabled = false;
    }

    try {
        var jsPDF = window.jspdf.jsPDF;
        var pdf = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
        var pageW = 297;
        var pageH = 210;
        var margin = 12;
        var contentW = pageW - margin * 2;
        var now = new Date();
        var dateStr = 'Generado: ' + now.toLocaleDateString('es-CO') + ' ' +
            now.toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' });

        // Header
        pdf.setFontSize(16);
        pdf.setFont(undefined, 'bold');
        pdf.setTextColor(30, 41, 59);
        pdf.text(pdfTitle || 'Analíticas de Consultas', margin, margin + 6);
        pdf.setFontSize(9);
        pdf.setFont(undefined, 'normal');
        pdf.setTextColor(100, 116, 139);
        pdf.text(dateStr, pageW - margin, margin + 6, { align: 'right' });
        pdf.setDrawColor(226, 232, 240);
        pdf.setLineWidth(0.4);
        pdf.line(margin, margin + 10, pageW - margin, margin + 10);

        // Filtros aplicados: deja constancia del alcance de los datos del informe.
        var headerBottom = margin + 14;
        var filterLines = [];
        if (filters && filters.length) {
            var parts = filters.map(function(f) { return f[0] + ': ' + f[1]; });
            filterLines = pdf.splitTextToSize('Filtros aplicados — ' + parts.join('  |  '), contentW);
        } else {
            filterLines = ['Filtros aplicados — ninguno (todos los datos)'];
        }
        pdf.setFontSize(7.5);
        pdf.setFont(undefined, 'normal');
        pdf.setTextColor(100, 116, 139);
        for (var fl = 0; fl < filterLines.length; fl++) {
            pdf.text(filterLines[fl], margin, headerBottom + fl * 3.6);
        }
        headerBottom += filterLines.length * 3.6 + 2;

        // Collect charts
        var chartBoxes = document.querySelectorAll('.rcv-chart-box');
        var items = [];
        chartBoxes.forEach(function(box) {
            var titleEl = box.querySelector('h3');
            var title = titleEl ? titleEl.textContent.trim() : '';
            var canvas = box.querySelector('canvas');
            if (!canvas) return;
            try {
                var chartInstance = Chart.getChart(canvas);
                var imgData = chartInstance
                    ? chartInstance.toBase64Image('image/png', 1)
                    : canvas.toDataURL('image/png');
                items.push({
                    title: title,
                    imgData: imgData,
                    origW: canvas.width,
                    origH: canvas.height
                });
            } catch (ex) {
                console.warn('Cannot export canvas', canvas.id, ex);
            }
        });

        // Collect tables via html2canvas
        var tableWrappers = document.querySelectorAll('.rcv-table-wrapper');
        var tablePromises = [];
        tableWrappers.forEach(function(tw) {
            var prev = tw.previousElementSibling;
            while (prev && !prev.classList.contains('rcv-section-title') && prev.tagName !== 'H4') {
                prev = prev.previousElementSibling;
            }
            var tableTitle = prev ? prev.textContent.trim() : '';
            tablePromises.push(
                html2canvas(tw, { scale: 2, useCORS: true, backgroundColor: '#ffffff' })
                    .then(function(c) {
                        return {
                            title: tableTitle,
                            imgData: c.toDataURL('image/png'),
                            origW: c.width,
                            origH: c.height
                        };
                    })
            );
        });

        Promise.all(tablePromises).then(function(tableItems) {
            var curY = headerBottom;
            var chartW = (contentW - 6) / 2;
            var chartH = 72;
            var titleH = 6;

            for (var i = 0; i < items.length; i += 2) {
                if (curY + titleH + chartH + 4 > pageH - margin) {
                    pdf.addPage();
                    curY = margin;
                }
                var left = items[i];
                pdf.setFontSize(9);
                pdf.setFont(undefined, 'bold');
                pdf.setTextColor(30, 41, 59);
                pdf.text(left.title, margin, curY + 4);
                pdf.addImage(left.imgData, 'PNG', margin, curY + titleH, chartW, chartH);

                if (i + 1 < items.length) {
                    var right = items[i + 1];
                    pdf.text(right.title, margin + chartW + 6, curY + 4);
                    pdf.addImage(right.imgData, 'PNG', margin + chartW + 6, curY + titleH, chartW, chartH);
                }
                curY += titleH + chartH + 8;
            }

            tableItems.forEach(function(tbl) {
                if (!tbl.imgData) return;
                var ratio = tbl.origW / tbl.origH;
                var tblW = contentW;
                var tblH = tblW / ratio;
                var maxTblH = pageH - margin * 2 - 10;
                if (tblH > maxTblH) { tblH = maxTblH; tblW = tblH * ratio; }

                if (curY + 8 + tblH > pageH - margin) {
                    pdf.addPage();
                    curY = margin;
                }
                if (tbl.title) {
                    pdf.setFontSize(10);
                    pdf.setFont(undefined, 'bold');
                    pdf.setTextColor(30, 41, 59);
                    pdf.text(tbl.title, margin, curY + 5);
                    curY += 8;
                }
                pdf.addImage(tbl.imgData, 'PNG', margin, curY, tblW, tblH);
                curY += tblH + 8;
            });

            var pageCount = pdf.getNumberOfPages();
            for (var p = 1; p <= pageCount; p++) {
                pdf.setPage(p);
                pdf.setFontSize(7);
                pdf.setFont(undefined, 'normal');
                pdf.setTextColor(148, 163, 184);
                pdf.text('RCV Analytics \u2014 ' + dateStr, margin, pageH - 5);
                pdf.text('P\u00e1gina ' + p + ' de ' + pageCount, pageW - margin, pageH - 5, { align: 'right' });
            }

            var filename = (filePrefix || 'consultas_analiticas') + '_' + now.getFullYear() +
                String(now.getMonth() + 1).padStart(2, '0') +
                String(now.getDate()).padStart(2, '0') + '.pdf';
            pdf.save(filename);
            cleanup();

        }).catch(function(err) {
            console.error('Error generating PDF:', err);
            alert('Error al generar el PDF: ' + err.message);
            cleanup();
        });

    } catch (e) {
        console.error('Error in rcvExportChartsPDF:', e);
        alert('Error al iniciar la exportaci\u00f3n: ' + e.message);
        cleanup();
    }
}
